<?php require '../includes/functions.php';$u=require_role('super_admin');verify_csrf();$pdo=db();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){try{if($_POST['action']==='department'){$name=trim($_POST['name']??'');if($name==='')throw new RuntimeException('Department name is required.');$pdo->prepare('INSERT INTO departments(name,description) VALUES(?,?)')->execute([$name,trim($_POST['description']??'')?:null]);$message='Department added.';}elseif($_POST['action']==='category'){$pdo->prepare('INSERT INTO categories(department_id,name,description) VALUES(?,?,?)')->execute([(int)$_POST['department_id'],trim($_POST['category_name']),trim($_POST['category_description']??'')?:null]);$message='Category added.';}elseif($_POST['action']==='toggle_department'){$pdo->prepare('UPDATE departments SET is_active=1-is_active WHERE id=?')->execute([(int)$_POST['id']]);$message='Department status changed.';}elseif($_POST['action']==='role'){$role=$_POST['role'];if(!in_array($role,['citizen','department_admin','super_admin'],true))throw new RuntimeException('Invalid role.');$dept=$role==='department_admin'?(int)$_POST['department_id']:null;$pdo->prepare('UPDATE users SET role_id=(SELECT id FROM roles WHERE name=?),department_id=? WHERE id=?')->execute([$role,$dept,(int)$_POST['user_id']]);$pdo->prepare('INSERT INTO audit_logs(user_id,action,entity_type,entity_id,details,ip_address) VALUES(?,?,?,?,?,?)')->execute([$u['id'],'role_changed','user',(int)$_POST['user_id'],'Role set to '.$role,$_SERVER['REMOTE_ADDR']??null]);$message='Account role updated.';}}catch(Throwable $e){$message=$e instanceof RuntimeException?$e->getMessage():'Could not save changes. Check that names are unique and fields are valid.';}}$depts=$pdo->query('SELECT * FROM departments ORDER BY name')->fetchAll();$users=$pdo->query('SELECT u.id,u.full_name,u.email,r.name role,u.department_id FROM users u JOIN roles r ON r.id=u.role_id ORDER BY u.created_at DESC LIMIT 200')->fetchAll();$pageTitle='System management';require '../includes/header.php';?><h1>System management</h1><?php if($message):?><p class="notice"><?=e($message)?></p><?php endif?><div class="grid"><section class="panel"><h2>Add department</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="department"><label>Name</label><input name="name" required maxlength="120"><label>Description</label><textarea name="description"></textarea><button>Add department</button></form></section><section class="panel"><h2>Add category</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="category"><label>Department</label><select name="department_id" required><?php foreach($depts as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach?></select><label>Category</label><input name="category_name" required maxlength="120"><label>Description</label><textarea name="category_description"></textarea><button>Add category</button></form></section></div><section class="panel"><h2>Departments</h2><table><tr><th>Name</th><th>Active</th><th></th></tr><?php foreach($depts as $d):?><tr><td><?=e($d['name'])?></td><td><?=$d['is_active']?'Yes':'No'?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle_department"><input type="hidden" name="id" value="<?=$d['id']?>"><button><?=$d['is_active']?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach?></table></section><section class="panel"><h2>Accounts and administrative roles</h2><p>Role grants are restricted to the super administrator. Assign one or more department admin accounts for processing.</p><table><tr><th>Name</th><th>Email</th><th>Current role</th><th>Set role</th></tr><?php foreach($users as $person):?><tr><td><?=e($person['full_name'])?></td><td><?=e($person['email'])?></td><td><?=e($person['role'])?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="role"><input type="hidden" name="user_id" value="<?=$person['id']?>"><select name="role"><option>citizen</option><option>department_admin</option><option>super_admin</option></select><select name="department_id"><option value="">Choose department</option><?php foreach($depts as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach?></select><button>Update</button></form></td></tr><?php endforeach?></table></section><?php require '../includes/footer.php';?>
